228:   function showEmptyRhymes() {
229:     ui.rhymeList.replaceChildren(...Array.from({ length: 4 }, () => {
230:       const chip = document.createElement('span');
231:       chip.className = 'rhyme-chip empty-chip';
232:       chip.textContent = '—';
233:       return chip;
234:     }));
235:     ui.revealNote.textContent = 'APARECE EN EL TIEMPO 3';
