239:     state.rhymeRevealed = true;
240:     ui.rhymeList.replaceChildren(...state.currentPrompt.rhymes.map((word, index) => {
241:       const chip = document.createElement('span');
242:       chip.className = 'rhyme-chip';
243:       chip.textContent = word;
